V.tch=()=>`<div class="card"><h3>Add teacher</h3><input id="tn" placeholder="Name"><input id="tj" placeholder="Subject"><input id="tp" placeholder="Phone"><button class="pri" onclick="f.addTch()">Add teacher</button></div>${TC.map(t=>`<div class="card"><b>${esc(t.name)}</b> <span class="mut">Roll ${t.roll} · ${esc(t.subject||'')}${t.active===false?' · Inactive':''}</span><label class="li"><span>Can publish results</span><input type="checkbox" style="width:auto;margin:0" ${t.pub?'checked':''} onchange="f.pubT('${t.id}',this.checked)"></label><p class="mut">Tick the batches this teacher can use:</p>${B.map(b=>`<label class="li"><span>${esc(b.name)}</span><input type="checkbox" style="width:auto;margin:0" ${(t.bids||[]).includes(b.id)?'checked':''} onchange="f.asg('${t.id}','${b.id}',this.checked)"></label>`).join('')||'<p class="mut">Add a batch first.</p>'}<button onclick="f.rp('${t.id}')">Reset password</button> <button onclick="f.tgT('${t.id}')">${t.active===false?'Reactivate':'Deactivate'}</button> <button onclick="f.del('${t.id}')">Delete</button></div>`).join('')||'<p class="mut">No teachers yet.</p>'}`;
