const again=()=>me.role=='student'?student():render();
f.sp=on=>{S.sp=on;student()};
f.pic=file=>{if(!file)return;const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),z=160,m=Math.min(im.width,im.height);c.width=c.height=z;c.getContext('2d').drawImage(im,(im.width-m)/2,(im.height-m)/2,m,m,0,0,z,z);const d=c.toDataURL('image/jpeg',.8);updateDoc(doc(db,'users',me.id),{pic:d}).then(()=>{me.pic=d;alert('Saved');again()}).catch(e=>alert(e.message))};im.src=URL.createObjectURL(file)};
f.saveP=async()=>{const x={phone:$('#pp').value.trim(),addr:$('#pa2').value.trim(),bg:$('#pbg').value};if(me.role=='student'){x.gname=$('#pg').value.trim();x.gphone=$('#pgp').value.trim()}try{await updateDoc(doc(db,'users',me.id),x);Object.assign(me,x);alert('Saved')}catch(e){alert(e.message)}};
f.pw=async()=>{const v=$('#pw1').value;if(v.length<6)return alert('Password must be at least 6 characters');try{await updatePassword(auth.currentUser,v);$('#pw1').value='';alert('Password changed')}catch(e){alert(e.code=='auth/requires-recent-login'?'Please logout and login again, then try once more.':e.message)}};
