function ZL(cls,grp,sd){const R=ZL0(cls,grp,sd),c=+cls;if(!c)return R;const ex=[['বাংলা ১ম পত্র',ZB1[c]],['English 1st Paper',ZE1[c]],['ইসলাম ও নৈতিক শিক্ষা',ZIS[c]]].filter(e=>e[1]).map(([s,t])=>({s,t}));const all=[...ex,...R],rk=s=>{const i=ZORD.indexOf(s);return i<0?99:i};return all.map((x,i)=>[x,i]).sort((a,b)=>rk(a[0].s)-rk(b[0].s)||a[1]-b[1]).map(a=>a[0])}
function ZL0(cls,grp,sd){cls=+cls;let L=[];if(ZNC[cls])L=Object.entries(ZNC[cls]);else if(cls==9||cls==10){L=Object.entries(Z910);const gs=grp&&ZG[grp]?[grp]:Object.keys(ZG),seen=new Set();gs.forEach(g=>Object.entries(ZG[g]).forEach(e=>{if(!seen.has(e[0])){seen.add(e[0]);L.push(e)}}))}
if(cls)L=[...L,['বাংলা ২য় পত্র',ZB2],['English 2nd Paper',ZE2]];return [...L.map(([s,t])=>({s,t})),...((sd&&sd.cx)||[]).filter(x=>!x.g||!grp||x.g==grp)]}
