const ZC='#0b3a8a',ZBX='border:1px solid #c9d8ee;background:#f4f8fe;border-radius:10px;padding:12px 14px',ZTD='padding:9px 8px;border:0;border-top:1px solid #dbe5f3',ZTH='padding:9px 8px;border:0;background:#e6efff;color:#0b2a5c;text-align:left';
