f.bDel=async()=>{const b=B.find(x=>x.id==S.bid),n=U.filter(x=>x.bid==b.id).length;if(n)return alert('This batch still has '+n+' student(s). Move them to another batch or delete them first.');if(!confirm('Delete batch "'+b.name+'"? This cannot be undone.'))return;
await Promise.all(TC.filter(t=>(t.bids||[]).includes(b.id)).map(t=>updateDoc(doc(db,'users',t.id),{bids:t.bids.filter(i=>i!=b.id)})));await deleteDoc(doc(db,'batches',b.id));S.bid=null;render()};
f.del=async id=>{const u=U.find(x=>x.id==id)||TC.find(x=>x.id==id);if(!u)return;if(u.ca)return alert('Remove co-admin access first.');
if(!confirm('Delete '+u.name+' permanently? Their login stops working. Old marks and records stay.')||!confirm('Really delete '+u.name+'?'))return;
await deleteDoc(doc(db,'users',id));try{await deleteDoc(doc(db,'login',String(u.roll).toLowerCase()))}catch(e){}if(u.bid)recalc(u.bid).catch(()=>{});render()};
V.cap=async()=>{const cos=TC.filter(t=>t.ca),oth=TC.filter(t=>!t.ca&&t.active!==false);let L=[];try{L=(await snap('log')).sort((a,b)=>b.t-a.t).slice(0,60)}catch(e){}
return `<div class="card"><h3>Co-admins (${cos.length} / 3)</h3>${cos.map(t=>`<div class="li"><span><a class="lk" onclick="f.info('${t.id}')">${esc(t.name)}</a><br><span class="mut">${esc(t.subject||'')} · ${t.roll}</span></span><button onclick="f.ca('${t.id}',false)">Remove</button></div>`).join('')||'<p class="mut">No co-admin yet.</p>'}${cos.length<3&&oth.length?`<select id="cap">${oth.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="pri" onclick="f.capAdd()">Appoint co-admin</button>`:''}</div>
<div class="card"><h3>What co-admins did</h3>${L.map(x=>`<div class="li"><span>${esc(x.msg)}<br><span class="mut">${esc(x.by)} · ${new Date(x.t).toLocaleString()}</span></span></div>`).join('')||'<p class="mut">Nothing yet.</p>'}</div>`};
f.capAdd=()=>{const v=$('#cap').value;if(v)f.ca(v,true)};
const LGm={addStu:'Added a student',addTch:'Added a teacher',tg:"Changed a student's status",tgT:"Changed a teacher's status",del:'Deleted a student/teacher',bDel:'Deleted a batch',addB:'Added a batch',rp:'Reset a password',addPay:'Added a fee payment',newMonth:'Started a new month',setStart:'Changed the month start date',saveDay:'Saved attendance',saveEx:'Saved exam marks',pub:'Published or hid exam results',sr:'Published or hid a progress report',rqAct:'Handled a request',zAS:'Added a student to a batch',zAT:'Added a teacher to a batch',zCls:'Changed the class of a batch'};
Object.keys(LGm).forEach(k=>{const o=f[k];if(o)f[k]=async(...a)=>{const r=await o(...a);if(me.co)addDoc(collection(db,'log'),{uid:me.id,by:me.name,msg:LGm[k]+((B.find(b=>b.id==S.bid)||{}).name?' ('+(B.find(b=>b.id==S.bid)||{}).name+')':''),t:Date.now()}).catch(()=>{});return r}});
Object.assign(BN,{"Co-admin panel":"কো-অ্যাডমিন প্যানেল","Delete":"মুছুন","Delete this batch":"এই ব্যাচ মুছুন","Group":"গ্রুপ","All groups":"সব গ্রুপ","Appoint co-admin":"কো-অ্যাডমিন নিয়োগ দিন","What co-admins did":"কো-অ্যাডমিনরা কী করেছেন","Remove":"সরান","No co-admin yet.":"এখনো কোনো কো-অ্যাডমিন নেই।","Pick a group to see only that group's subjects and students.":"গ্রুপ বেছে নিলে শুধু সেই গ্রুপের বিষয় ও ছাত্র দেখাবে।"});

// ---- self registration + admin approval + email ----
function regForm(m=''){out(`<div class="card"><h2>Registration</h2><p class="mut">${m||'Fill the form. After the admin approves, your roll number and temporary password are sent to your email.'}</p>
<select id="rr" onchange="f.rr()"><option value="student">Student</option><option value="teacher">Teacher</option></select><input id="rn" placeholder="Full name">
<div id="rs1">${clsSel('rcl','')}<input id="rsc" placeholder="School / College"><select id="rgp"><option value="">Group (SSC/HSC only)</option><option>Science</option><option>Commerce</option><option>Arts</option></select></div>
<div id="rt1" hidden><input id="rsb" placeholder="Subject you teach"><input id="rcc" placeholder="Classes you teach, e.g. 9-10"></div>
<input id="rph" type="tel" placeholder="Phone"><input id="rem" type="email" placeholder="Email (your login details will be sent here)"><input id="rad" placeholder="Present address"><button class="pri" onclick="f.regSend()">Send registration</button> <button onclick="f.regBack()">Back</button></div>`)}
f.rr=()=>{const t=$('#rr').value=='teacher';$('#rs1').hidden=t;$('#rt1').hidden=!t};
f.regBack=()=>login();
f.regSend=async()=>{const v=id=>($('#'+id).value||'').trim(),role=v('rr'),n=v('rn'),em2=v('rem');if(!n||!v('rph')||!em2.includes('@'))return alert('Please enter your name, phone and a valid email');
const d={role,name:n,phone:v('rph'),email:em2,addr:v('rad'),st:'pending',t:Date.now()};if(role=='student'){d.cls=v('rcl');d.school=v('rsc');d.grp=v('rgp')}else{d.subject=v('rsb');d.cls=v('rcc')}
try{await addDoc(collection(db,'reg'),d);alert('Registration sent. Please wait for the admin to approve it. You will get your login details by email.');login()}catch(e){alert('Could not send: '+e.message)}};
const mailCfg=async()=>{try{const q=await getDoc(doc(db,'config','mail'));return q.exists()?q.data():{}}catch(e){return{}}};
async function sendMail(to,name,roll,pw){const m=await mailCfg();if(!m.pk||!m.sid||!m.tid)return 'Email is not set up yet';
try{const x=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:m.sid,template_id:m.tid,user_id:m.pk,template_params:{to_email:to,to_name:name,roll,password:pw,site:location.origin+location.pathname}})});return x.ok?'':'Email service said: '+(await x.text())}catch(e){return 'Network error'}}
V.reg=async()=>{const R=(await snap('reg')).sort((a,b)=>b.t-a.t).filter(r=>r.st=='pending'),mc=await mailCfg();
return `<div class="card"><details><summary>Email setup (EmailJS, free)</summary><p class="mut">Create a free account at emailjs.com, connect your email, make a template that uses {{to_email}}, {{to_name}}, {{roll}} and {{password}}, then paste the 3 keys here.</p><input id="mk" placeholder="Public key" value="${esc(mc.pk||'')}"><input id="ms" placeholder="Service ID" value="${esc(mc.sid||'')}"><input id="mt" placeholder="Template ID" value="${esc(mc.tid||'')}"><button class="pri" onclick="f.mailSave()">Save</button></details></div>
${R.map(r=>`<div class="card"><b>${esc(r.name)}</b> <span class="mut">${r.role=='teacher'?'Teacher':'Student'}</span><p class="mut">${esc(r.phone||'')} · ${esc(r.email||'')}<br>${r.role=='teacher'?'Subject: '+esc(r.subject||'–')+' · Classes: '+esc(r.cls||'–'):'Class '+esc(r.cls||'–')+(r.grp?' · '+esc(r.grp):'')+'<br>'+esc(r.school||'')}<br>${esc(r.addr||'')}</p>${r.role=='student'?`<select id="rb${r.id}">${B.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select>`:''}<button class="pri" onclick="f.rgOk('${r.id}')">Approve</button> <button onclick="f.rgNo('${r.id}')">Reject</button></div>`).join('')||'<div class="card"><p class="mut">No pending registrations.</p></div>'}`};
f.mailSave=async()=>{await setDoc(doc(db,'config','mail'),{pk:$('#mk').value.trim(),sid:$('#ms').value.trim(),tid:$('#mt').value.trim()});alert('Saved')};
f.rgNo=async id=>{if(confirm('Reject this registration?')){await updateDoc(doc(db,'reg',id),{st:'rejected'});render()}};
f.rgOk=async id=>{const r=(await getDoc(doc(db,'reg',id))).data(),st=r.role=='student';let bid='';if(st){bid=($('#rb'+id)||{}).value;if(!bid)return alert('Create a batch first, then approve.')}
let roll;do roll=String(100000+Math.floor(Math.random()*900000));while(U.some(s=>s.roll==roll)||TC.some(s=>s.roll==roll));
const pw=Math.random().toString(36).slice(2,8)+'A1',a2=getAuth(initializeApp(cfg,'s'+Date.now()));
try{const c=await createUserWithEmailAndPassword(a2,em(roll),pw);await signOut(a2);
await setDoc(doc(db,'users',c.user.uid),st?{role:'student',name:r.name,roll,bid,school:r.school||'',grp:r.grp||'',phone:r.phone||'',addr:r.addr||'',email:r.email||'',active:true,mustChange:true}:{role:'teacher',name:r.name,roll,subject:r.subject||'',phone:r.phone||'',addr:r.addr||'',email:r.email||'',bids:[],active:true,mustChange:true});
await updateDoc(doc(db,'reg',id),{st:'approved',roll});const err=await sendMail(r.email,r.name,roll,pw);
alert(err?'Approved, but the email was not sent ('+err+').\nGive this to '+r.name+':\nRoll: '+roll+'\nPassword: '+pw:'Approved. Login details were emailed to '+r.email+'.');render()}catch(e){alert(e.message)}};
Object.assign(BN,{"Registrations":"রেজিস্ট্রেশন","New registration":"নতুন রেজিস্ট্রেশন","Registration":"রেজিস্ট্রেশন","Send registration":"রেজিস্ট্রেশন পাঠান","No pending registrations.":"কোনো অপেক্ষমাণ রেজিস্ট্রেশন নেই।","Full name":"পুরো নাম","School / College":"স্কুল / কলেজ"});

// ---- admin login by name/email, new roll format REAS-YYYY-001 / REAT-YYYY-001 ----
f.adminMail=async()=>{const e=$('#pem').value.trim().toLowerCase();if(!e.includes('@'))return alert('Enter a valid email');await setDoc(doc(db,'login',e),{e:auth.currentUser.email});alert('Saved. You can now log in with this email or your name.')};
f.rgOk=async id=>{const r=(await getDoc(doc(db,'reg',id))).data(),st=r.role=='student';let bid='';if(st){bid=($('#rb'+id)||{}).value;if(!bid)return alert('Create a batch first, then approve.')}
const yr=new Date(r.t||Date.now()).getFullYear(),k=(st?'S':'T')+yr,cr=doc(db,'config','ctr'),cs=await getDoc(cr),pre='REA'+(st?'S':'T')+'-'+yr+'-';let n=(cs.exists()&&cs.data()[k])||0;
[...U,...TC].forEach(x=>{const v=String(x.roll||'');if(v.startsWith(pre))n=Math.max(n,+v.slice(pre.length)||0)});
const pw=Math.random().toString(36).slice(2,8)+'A1';
for(let i=0;i<10;i++){n++;const roll=pre+String(n).padStart(3,'0'),a2=getAuth(initializeApp(cfg,'s'+Date.now()+i));
try{const c=await createUserWithEmailAndPassword(a2,em(roll),pw);await signOut(a2);
await setDoc(doc(db,'users',c.user.uid),st?{role:'student',name:r.name,roll,bid,school:r.school||'',grp:r.grp||'',phone:r.phone||'',addr:r.addr||'',email:r.email||'',active:true,mustChange:true}:{role:'teacher',name:r.name,roll,subject:r.subject||'',phone:r.phone||'',addr:r.addr||'',email:r.email||'',bids:[],active:true,mustChange:true});
await setDoc(cr,{[k]:n},{merge:true});await updateDoc(doc(db,'reg',id),{st:'approved',roll});const err=await sendMail(r.email,r.name,roll,pw);
alert(err?'Approved, but the email was not sent ('+err+').\nGive this to '+r.name+':\nRoll: '+roll+'\nPassword: '+pw:'Approved. Login details were emailed to '+r.email+'.');return render()}
catch(e){if(e.code!='auth/email-already-in-use')return alert(e.message)}}
alert('Could not create a roll number. Please try again.')};
Object.assign(BN,{"Roll / Email / Name":"রোল / ইমেইল / নাম","Login with email":"ইমেইল দিয়ে লগইন","You can log in with your name or this email.":"আপনি নাম বা এই ইমেইল দিয়ে লগইন করতে পারবেন।","Email":"ইমেইল"});

// ---- batch group, same roll format for admin-added accounts ----
const grpSel=(id,v)=>`<select id="${id}"><option value="">Group (all)</option>${['Science','Commerce','Arts'].map(g=>`<option ${v==g?'selected':''}>${g}</option>`).join('')}</select>`;
const logCo=m=>{if(me.co)addDoc(collection(db,'log'),{uid:me.id,by:me.name,msg:m+((B.find(b=>b.id==S.bid)||{}).name?' ('+(B.find(b=>b.id==S.bid)||{}).name+')':''),t:Date.now()}).catch(()=>{})};
async function mkAcct(st,data){const yr=new Date().getFullYear(),k=(st?'S':'T')+yr,pre='REA'+(st?'S':'T')+'-'+yr+'-',cr=doc(db,'config','ctr'),cs=await getDoc(cr);let n=(cs.exists()&&cs.data()[k])||0;
[...U,...TC].forEach(x=>{const v=String(x.roll||'');if(v.startsWith(pre))n=Math.max(n,+v.slice(pre.length)||0)});const pw=Math.random().toString(36).slice(2,8)+'A1';
for(let i=0;i<10;i++){n++;const roll=pre+String(n).padStart(3,'0'),a2=getAuth(initializeApp(cfg,'s'+Date.now()+i));
try{const c=await createUserWithEmailAndPassword(a2,em(roll),pw);await signOut(a2);await setDoc(doc(db,'users',c.user.uid),{...data,role:st?'student':'teacher',roll,active:true,mustChange:true});await setDoc(cr,{[k]:n},{merge:true});return{roll,pw}}
catch(e){if(e.code!='auth/email-already-in-use')throw e}}throw new Error('Could not create a roll number. Please try again.')}
f.addStu=async()=>{const n=$('#sn').value.trim();if(!n)return alert('Enter the name');try{const a=await mkAcct(true,{name:n,bid:S.bid,gphone:$('#sg').value,school:$('#ss').value,grp:$('#sgp').value});logCo('Added a student');alert('Roll (username): '+a.roll+'\nPassword: '+a.pw+'\nGive this to the student.');render()}catch(e){alert(e.message)}};
f.addTch=async()=>{const n=$('#tn').value.trim();if(!n)return alert('Enter the name');try{const a=await mkAcct(false,{name:n,subject:$('#tj').value,phone:$('#tp').value,bids:[]});logCo('Added a teacher');alert('Roll (username): '+a.roll+'\nPassword: '+a.pw+'\nGive this to the teacher.');render()}catch(e){alert(e.message)}};
Object.assign(BN,{"Class and group of this batch (teachers of this batch see only this syllabus)":"এই ব্যাচের ক্লাস ও গ্রুপ (এই ব্যাচের শিক্ষকরা শুধু এই সিলেবাস দেখবেন)","Save class and group":"ক্লাস ও গ্রুপ সংরক্ষণ","Group (all)":"গ্রুপ (সব)"});
